#!/usr/bin/env bash
# Reproduce the reverse-export locator loop, apply the gateway /64 fix
# generated by gen-gateway-locator-config.sh, and check the result.
#
#   RELEASE=/tmp/midr-<id> midr-test/route-export-lab/test.sh
#
# Needs containerlab, the frr-midr-p6 image and a release built by
# tools/midr-deploy/build-release.sh.  Work files go to MIDR_LAB_WORK
# (default /tmp/midr-route-export-lab); the lab is left running for
# inspection, remove it with
#   containerlab destroy -t /tmp/midr-route-export-lab/midr-loop.clab.yaml --cleanup
set -uo pipefail
SRC=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)
LAB=${MIDR_LAB_WORK:-/tmp/midr-route-export-lab}
: "${RELEASE:?set RELEASE to a midr-* release directory}"
TOOLS=${TOOLS:-$(CDPATH= cd -- "$SRC/../../tools/midr-deploy" && pwd -P)}
export RELEASE TOOLS MIDR_LAB_WORK=$LAB
mkdir -p "$LAB"
PASS=0; FAIL=0
ok() { echo "[PASS] $*"; PASS=$((PASS + 1)); }
bad() { echo "[FAIL] $*"; FAIL=$((FAIL + 1)); }
X() { docker exec "clab-midr-loop-$1" bash -c "$2"; }
VT() { X "$1" "LD_LIBRARY_PATH=/opt/midr/lib:/opt/hostlib /opt/midr/vtysh --vty_socket /run/midr $2 2>/dev/null"; }
nh() { X gwb "ip -6 route get $1" 2>&1 | grep -o 'dev [^ ]*' | head -1; }  # eth1: toward mb (MIDR), eth2: underlay
ping_ok() { X gwb "ping -6 -c1 -W1 -I 2001:db8:b:10::1 2001:db8:a:10::1" >/dev/null 2>&1; }
session_up() { X ma "python3 /opt/midr/midrd-vty.py --socket /run/midr/midrd.vty -c 'show midr neighbors'" 2>/dev/null | grep -q Established; }
gre_tx() { X mb 's=0; for d in /sys/class/net/*; do [ "$(cat $d/type)" = 823 ] && s=$((s + $(cat $d/statistics/tx_packets))); done; echo $s'; }

sample() {  # label, rounds: record locator next hop, session and ping
    local label=$1 rounds=$2 loop=0 down=0 lost=0 i
    for ((i = 0; i < rounds; i++)); do
        [ "$(nh 2001:db8:a:1::2)" = "dev eth1" ] && loop=$((loop + 1))
        session_up || down=$((down + 1))
        ping_ok || lost=$((lost + 1))
        sleep 2
    done
    echo "$label: rounds=$rounds locator-via-MIDR=$loop session-down=$down ping-lost=$lost"
    SAMPLE="$loop $down $lost"
}

containerlab destroy -t "$LAB/midr-loop.clab.yaml" --cleanup >/dev/null 2>&1
bash "$SRC/gen.sh" >/dev/null
( . "$TOOLS/lib/profile.sh"; midr_profile_load "$LAB/profile" >/dev/null; midr_locator_prefixes ) >"$LAB/locators.txt"
containerlab deploy -t "$LAB/midr-loop.clab.yaml" >/dev/null 2>&1 || { echo 'deploy failed'; exit 1; }
for n in gwa gwb ma mb; do X $n "bash /lab/node.sh $n"; done

echo '== Generated export configuration on ma'
X ma "sed -n '/MIDR route export/,\$p' /etc/midr/bgpd.conf"

for i in $(seq 90); do
    X mb "ip -6 route show proto 199" | grep -q '2001:db8:a::/48' && \
    VT gwb "-c 'show bgp ipv6 unicast 2001:db8:a::/48'" | grep -q 'localpref 200' && break
    sleep 2
done
X mb "ip -6 route show proto 199" | grep -q '2001:db8:a::/48' && ok "mb installed site A /48 from MIDR (proto 199)" || bad "mb has no MIDR route for site A"
VT gwb "-c 'show bgp ipv6 unicast 2001:db8:a::/48'" | grep -q 'localpref 200' && ok "gwb learned site A /48 from mb (reverse export)" || bad "gwb did not learn the exported route"
VT gwb "-c 'show bgp ipv6 unicast 2001:db8:a::/48'" | grep -q 'no-export' && ok "gateway keeps the exported route inside its AS (no-export)" || bad "no-export missing"

echo '== Before fix'
X gwb "ip -6 route get 2001:db8:a:1::2"
sample before 20
read -r loop down lost <<<"$SAMPLE"
[ "$loop" -gt 0 ] && ok "loop reproduced: gwb sends remote-locator traffic back to mb ($loop/20)" || bad "loop not reproduced"
{ [ "$down" -gt 0 ] || [ "$lost" -gt 0 ]; } && ok "control session or business ping disrupted (down=$down lost=$lost)" || bad "no disruption seen"
X ma "grep -cE 'session.*(down|closed|timeout)|hold' /var/log/midr/ma-midrd.log" | sed 's/^/ma midrd session-loss log lines: /'

echo '== Apply gateway fix generated by gen-gateway-locator-config.sh'
"$TOOLS/gen-gateway-locator-config.sh" --profile "$LAB/profile" --node ma --asn 65001 | tee "$LAB/gwa-fix.conf"
"$TOOLS/gen-gateway-locator-config.sh" --profile "$LAB/profile" --node mb --asn 65002 >"$LAB/gwb-fix.conf"
for s in a b; do
    docker cp "$LAB/gw$s-fix.conf" "clab-midr-loop-gw$s:/tmp/fix.conf" >/dev/null
    VT gw$s "-f /tmp/fix.conf" >/dev/null
done
for i in $(seq 60); do
    [ "$(nh 2001:db8:a:1::2)" = "dev eth2" ] && session_up && ping_ok && break
    sleep 2
done
sleep 20

echo '== After fix'
X gwb "ip -6 route get 2001:db8:a:1::2"
X gwb "ip -6 route get 2001:db8:a:10::1"
sample after 30
read -r loop down lost <<<"$SAMPLE"
[ "$loop" -eq 0 ] && [ "$(nh 2001:db8:a:1::2)" = "dev eth2" ] && ok "gwb reaches remote locator through the underlay" || bad "locator still routed via MIDR ($loop)"
[ "$down" -eq 0 ] && ok "MIDR session stayed Established for 60 s" || bad "session down in $down samples"
[ "$lost" -eq 0 ] && ok "business ping b:10::1 -> a:10::1 never lost" || bad "ping lost $lost/30"
[ "$(nh 2001:db8:a:10::1)" = "dev eth1" ] && ok "business traffic still enters MIDR at mb" || bad "business traffic bypasses MIDR: $(nh 2001:db8:a:10::1)"
before=$(gre_tx | tail -1)
X gwb "ping -6 -c20 -i0.05 -W1 -q -I 2001:db8:b:10::1 2001:db8:a:10::1" | tail -2
after=$(gre_tx | tail -1)
[ -n "$before" ] && [ "$((after - before))" -ge 20 ] && ok "pings crossed the GRE virtual link (tx +$((after - before)))" || bad "GRE counters did not grow ($before -> $after)"
VT ma "-c 'show bgp ipv6 unicast 2001:db8:a:1::/64'" | grep -q 'Paths: (1 available' && ok "ma learned its locator /64 from gwa" || bad "ma did not learn its locator /64"
X mb "ip -6 route show proto 199" | grep -q '2001:db8:a:1::/64' && bad "locator /64 leaked into MIDR" || ok "locator /64 not imported into MIDR (Provider exclusion)"
VT gwb "-c 'show bgp ipv6 unicast 2001:db8:a:1::/64'" | grep -q 'localpref 200' && bad "mb exported a locator prefix" || ok "no locator prefix exported by MIDR"
echo '== mb MIDR routes'; X mb "ip -6 route show proto 199"
echo "RESULT pass=$PASS fail=$FAIL"
